"""Use the repository's paired timing driver for the simplified input contexts."""
import importlib
from functools import partial
from pathlib import Path
import sys

ROOT = Path('<repository-root>')
sys.path.insert(0, str(ROOT / 'scripts'))
import compare_builds as comparison

comparison.__file__ = __file__

for family in ('bessel', 'wignerd', 'vector_wave', 'spherical_translation'):
    for mode in ('jvp-value', 'jvp-only', 'grad'):
        @comparison.call(f'input-{family}-{mode}', framework='jax')
        def setup(tr, family=family, mode=mode):
            import jax
            import jax.numpy as jnp
            jax.config.update('jax_enable_x64', True)
            diff = importlib.import_module('treams_rs.diff')
            tj = importlib.import_module('treams_rs.jax')
            x = jnp.linspace(0.7, 1.1, 64)
            if family == 'bessel':
                record = partial(diff.bessel, 2)
            elif family == 'wignerd':
                record = partial(diff.wignerd, 2, 1, -1)
            elif family == 'vector_wave':
                record = partial(diff.vector_wave, function='vsw_rA', degree=2, order=1, pol=1)
            else:
                record = partial(diff.spherical_translation,
                                 destination=(2, 1, 1), source=(1, 0, 1), singular=False)
            if family == 'bessel':
                function = tj.wrap(record, x)
            else:
                wrapped = tj.wrap(record, x, jnp.asarray(0.6), jnp.asarray(0.3))
                function = lambda z: wrapped(z, jnp.asarray(0.6), jnp.asarray(0.3))
            if mode == 'grad':
                compiled = jax.jit(jax.grad(lambda z: jnp.real(function(z)).sum()))
            elif mode == 'jvp-only':
                compiled = jax.jit(lambda z: jax.jvp(function, (z,), (jnp.ones_like(z),))[1])
            else:
                compiled = jax.jit(lambda z: jax.jvp(function, (z,), (jnp.ones_like(z),)))
            return lambda: jax.block_until_ready(compiled(x))

for count in (1, 64):
    @comparison.call(f'input-native-bessel-n{count}')
    def native(tr, count=count):
        import numpy as np
        diff = importlib.import_module('treams_rs.diff')
        x = 0.7 if count == 1 else np.linspace(0.7, 1.1, count)
        direction = np.ones_like(x)
        def run():
            value, context = diff.bessel(2, x)
            return value, context.pushforward(direction)
        return run

if __name__ == '__main__':
    raise SystemExit(comparison.main())
